import{_ as e,c as i,o as n,ag as a}from"./chunks/framework.Bw-5EFTY.js";const d=JSON.parse('{"title":"Installation, Activation & Licensing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/installation-activation-licensing.md","filePath":"guide/getting-started/installation-activation-licensing.md","lastUpdated":1756182610000}'),o={name:"guide/getting-started/installation-activation-licensing.md"};function l(s,t,r,u,g,c){return n(),i("div",null,t[0]||(t[0]=[a('<h1 id="installation-activation-licensing" tabindex="-1">Installation, Activation &amp; Licensing <a class="header-anchor" href="#installation-activation-licensing" aria-label="Permalink to &quot;Installation, Activation &amp; Licensing&quot;">​</a></h1><p>Installing and activating FluentAffiliate is a quick and easy process. This guide will walk you through the steps to install, upgrade, and activate your FluentAffiliate license so you can start managing your affiliate program right away.</p><h3 id="step-1-install-fluentaffiliate-free-version" tabindex="-1">Step 1. Install FluentAffiliate (Free Version) <a class="header-anchor" href="#step-1-install-fluentaffiliate-free-version" aria-label="Permalink to &quot;Step 1. Install FluentAffiliate (Free Version)&quot;">​</a></h3><p>This is the standard method for installing the core FluentAffiliate plugin, which is free and available from the WordPress Plugin Directory. After downloading the plugin, follow the steps below:</p><ol><li>Navigate to your WordPress dashboard.</li><li>Go to <strong>Plugins</strong> &gt; <strong>Add New</strong>.</li><li>In the search bar, type &quot;<strong>FluentAffiliate</strong>&quot; and press <strong>Enter</strong>.</li><li>Locate the &quot;<strong>FluentAffiliate</strong>&quot; plugin in the search results and click &quot;<strong>Install Now</strong>&quot;.</li><li>Once installed, click &quot;<strong>Activate</strong>&quot;. You can now use the <strong>FluentAffiliate</strong> plugin.</li></ol><h3 id="step-2-installing-fluentaffiliate-pro-requires-base-plugin" tabindex="-1">Step 2. Installing FluentAffiliate Pro (Requires Base Plugin) <a class="header-anchor" href="#step-2-installing-fluentaffiliate-pro-requires-base-plugin" aria-label="Permalink to &quot;Step 2. Installing FluentAffiliate Pro (Requires Base Plugin)&quot;">​</a></h3><p>If you have purchased FluentAffiliate Pro for advanced features, you will need to upload and activate them. Ensure the Free Base Plugin (from step 1) is already installed and active before proceeding with Pro Addons.</p><ol><li>Download the FluentAffiliate Pro <strong>.zip</strong> file from your <a href="https://wpmanageninja.com/account/" target="_blank" rel="noreferrer">WPManageNinja dashboard</a>.</li><li>Navigate to your WordPress dashboard.</li><li>Go to <strong>Plugins</strong> &gt; <strong>Add New</strong>.</li><li>At the top of the page, click the &quot;<strong>Upload Plugin</strong>&quot; button.</li><li>Click &quot;<strong>Choose File</strong>&quot;, then select the <strong>FluentAffiliate Pro .zip</strong> file you downloaded.</li><li>Click &quot;<strong>Install Now</strong>&quot;.</li><li>Once the installation is complete, click &quot;<strong>Activate Plugin</strong>&quot;.</li></ol><h3 id="step-3-activating-your-fluentaffiliate-pro-license" tabindex="-1">Step 3. Activating Your FluentAffiliate Pro License <a class="header-anchor" href="#step-3-activating-your-fluentaffiliate-pro-license" aria-label="Permalink to &quot;Step 3. Activating Your FluentAffiliate Pro License&quot;">​</a></h3><p>After installing the Pro, you will need to activate your license key. This is essential to receive automatic updates, bug fixes, new features, and access to our support for your Pro Addons.</p><ol><li>When you turn on the Pro, you might see an activation notice directly in your WordPress dashboard. You can click on this notice to start the activation process.</li><li>Alternatively, navigate to the FluentAffiliate Dashboard in your WordPress admin area.</li><li>In the left sidebar, go to <strong>FluentAffiliate Pro</strong> &gt; <strong>Settings</strong>.</li><li>Click on the &quot;<strong>License Management</strong>&quot; tab.</li><li>In the &quot;<strong>License Key</strong>&quot; field, enter the unique license key you received upon purchasing <strong>FluentAffiliate Pro</strong> from <strong>WPManageNinja</strong>.</li><li>Click the &quot;<strong>Verify License</strong>&quot; button.</li></ol><p>That&#39;s it! You&#39;ve successfully installed, activated, and licensed FluentAffiliate.</p>',12)]))}const h=e(o,[["render",l]]);export{d as __pageData,h as default};
